import{_ as m,l as d,o as e,c,v as o,p,x as r,d as s,i,S as l}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"mmap","description":"","frontmatter":{"title":"mmap","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mmap.md","filePath":"cs/mmap.md","lastUpdated":1789023840000}'),n={name:"cs/mmap.md"};function E(h,a,A,_,B,f){const t=d("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="mmap" tabindex="-1">mmap <a class="header-anchor" href="#mmap" aria-label="Permalink to &quot;mmap&quot;">​</a></h1><div class="epigraph"><p>把文件或匿名页映射进进程地址空间：访存即 I/O，缺页即按需读，脏页即延迟写回。</p><footer>—— 据 POSIX mmap；Bach 与 Silberschatz 对内存映射文件的整理</footer></div><p><a href="/cs/cow-fork">上一课</a>让页在进程间按写拆分。<a href="/cs/cow-fork">地址空间布局</a>留出映射区。<code>read</code> 把文件拷进用户缓冲，再拷进堆，同一字节可能三份。<a href="/cs/demand-paging">按需调页</a>已能在缺页时从文件填页。缺口是把文件<strong>直接</strong>接到虚地址：mmap。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加载器对文本段实际上已经在做映射；用户还要对数据文件、共享库、匿名堆做同样的事。缺口不是新的磁盘格式，而是系统调用：选定虚区间、绑定文件偏移或匿名、权限、是否与其他进程共享。访问走普通 load/store；第一次触及才读磁盘；写脏后由内核在置换或 <code>msync</code> 时写回。</p><p>本课不把 <code>madvise</code> 的全部提示写完。</p><p><span class="marginnote"><code>MAP_SHARED</code> 写可见于文件与其他映射者；<code>MAP_PRIVATE</code> 对文件是 COW：写不污染文件，拆页与上一课相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>mmap 在 VMA（虚区间描述）里记下文件与偏移。缺页：算文件块，读入帧，填页表。共享映射的同一文件页可被多进程页表指向，像 fork 之前的共享，但来源是文件不是父进程。匿名 mmap 给堆、给线程栈后备，替代或补充 <code>brk</code>。</p>',9)),(e(),p(l,null,{default:r(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22mmap%20%E5%BB%BA%E8%99%9A%E5%8C%BA%E9%97%B4%22%5D%20--%3E%20TOUCH%5B%22%E7%AC%AC%E4%B8%80%E6%AC%A1%E8%AE%BF%E9%97%AE%22%5D%0A%20%20TOUCH%20--%3E%20PG%5B%22%E7%BC%BA%E9%A1%B5%E8%AF%BB%E6%96%87%E4%BB%B6%E6%88%96%E9%9B%B6%E9%A1%B5%22%5D%0A%20%20PG%20--%3E%20DIRTY%5B%22%E5%86%99%E5%88%99%E6%A0%87%E8%84%8F%22%5D%0A%20%20DIRTY%20--%3E%20WB%5B%22%E5%90%8E%E8%AF%BE%3A%20%E7%BC%93%E5%86%B2%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>mmap 把文件变成<a href="/cs/locality-principle">局部性</a>可利用的页 Cache：热点页留在帧里，与后课缓冲脏页是同一层对象。相对 <code>read</code>，少一次用户缓冲拷贝。代价是：短请求的系统调用开销被换成缺页；错误（I/O 失败）出现在信号或下次故障，而不是 <code>read</code> 的返回值——边界里要承认。</p><p>动态链接的 <code>.so</code> 用共享 mmap 文本，多进程一份物理页，这是加载课与本课的接头。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把数据库用 mmap 当缓冲池的全部争议写完。不引入 <code>mmap</code> 与 64 位空洞的实现上限表。I/O 错误异步化是接口裂缝，主干点名即可。真正的「文件是什么」还没有：下一课才把文件收成字节流抽象。</p><p>文件尾延伸与映射长度不一致时，访问超出文件的页如何处理由实现规定；主干避免把映射做得比文件长还当普通堆。</p><p>后课默认：虚区间可以绑文件。文件作为内核对象如何命名、如何读写，下一课从字节流讲起。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mmap 把文件或匿名页接到虚地址；缺页即读。</li><li>PRIVATE 是对文件的 COW；SHARED 写回文件。</li><li>文件对象本身是下一课的抽象。</li><li>出处：POSIX.1 mmap；Silberschatz et al., <em>OSC</em>；Bach, <em>UNIX</em>。</li></ul>',9))])}const T=m(n,[["render",E]]);export{P as __pageData,T as default};
